import os
import torch
import random
import numpy as np


class Config:
    # --- General ---
    SEED = 42
    DEBUG = False  # Set to True to use a small subset of data for debugging
    EXPERIMENT_NAME = "idea_25"

    # --- Paths ---
    # Input metadata paths (generated by the metadata script)
    TRAIN_PATH = "./metadata/train.csv"
    VAL_PATH = "./metadata/val.csv"
    TEST_PATH = "./metadata/test.csv"
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Output paths
    WORKING_DIR = f"./working/{EXPERIMENT_NAME}"
    CACHE_DIR = f"./working/{EXPERIMENT_NAME}/cache"
    MODEL_SAVE_PATH = f"./working/{EXPERIMENT_NAME}/model.pth"
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = "./submission/submission.csv"

    # --- Data Processing ---
    # Features to use
    CONT_FEATURES = ["time_step", "u_in", "R", "C"]
    # Derived physics features will be calculated in the dataset class
    # u_out is treated separately as a mask/binary control

    # Scaling
    SCALER_TYPE = "RobustScaler"

    # --- Model Architecture (Uniform-Capacity) ---
    D_MODEL = 512  # Uniform width throughout the network
    LSTM_HIDDEN = 256  # Bidirectional LSTM: 256 * 2 = 512 (matches D_MODEL)
    NUM_LAYERS = 4  # Number of Composite Blocks
    EXPANSION_FACTOR = 2  # Feed-Forward expansion (512 -> 1024 -> 512)
    DROPOUT = 0.1
    USE_AUXILIARY = True  # Enable auxiliary regression head
    AUX_WEIGHT = 0.3  # Weight for auxiliary loss

    # Stem Configuration
    STEM_KERNELS = [3, 5, 7]  # Multi-scale convolution kernels

    # --- Training ---
    EPOCHS = 30  # Optimized horizon for OneCycleLR
    BATCH_SIZE = 512  # Sufficient update budget
    LEARNING_RATE = 1e-3  # Max LR for OneCycle
    WEIGHT_DECAY = 1e-2
    GRAD_CLIP = 1.0  # Strict gradient clipping for LSTM stability

    # Scheduler
    SCHEDULER_PCT_START = 0.3  # Percentage of training to increase LR

    # --- Hardware ---
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """Creates necessary directories and sets random seeds."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set Reproducibility
        random.seed(cls.SEED)
        np.random.seed(cls.SEED)
        torch.manual_seed(cls.SEED)
        torch.cuda.manual_seed_all(cls.SEED)

        # For deterministic behavior (may slow down training slightly)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False


# Initialize setup immediately when module is imported
Config.setup()
